<script setup lang="ts">
import { computed } from 'vue'
import { useRouter } from 'vue-router'
import { ArrowRight, Award, CalendarDays, ChevronRight, Clock3, Flame, Play, Plus, TrendingUp } from '@lucide/vue'
import { routineSubtitle, useAppStore, workoutDuration, workoutVolume } from '@/stores/app'
const store=useAppStore();const router=useRouter();const date=computed(()=>new Intl.DateTimeFormat('en',{weekday:'long',month:'long',day:'numeric'}).format(new Date()));const recommended=computed(()=>store.routineList[store.history.length%Math.max(store.routineList.length,1)]??store.routineList[0]);const weeklyMinutes=computed(()=>store.workoutsThisWeek.reduce((sum,w)=>sum+workoutDuration(w),0));const latestPr=computed(()=>{const sets=store.history.flatMap(w=>w.exercises).flatMap(e=>e.sets.filter(s=>s.done).map(s=>({name:e.name,weight:s.weight,reps:s.reps}))).sort((a,b)=>b.weight-a.weight);return sets[0]??{name:'No record yet',weight:0,reps:0}})
function start(){if(store.activeWorkout){router.push('/workout');return}if(recommended.value)store.startRoutine(recommended.value.id);else store.startEmpty();router.push('/workout')}
function empty(){if(!store.activeWorkout)store.startEmpty();router.push('/workout')}
</script>
<template><div class="page dashboard-page"><header class="page-head"><div><span class="eyebrow">{{ date }}</span><h1>Good afternoon, {{ store.profile.name }}.</h1><p>{{ store.workoutsThisWeek.length>=store.profile.weeklyGoal?'Weekly goal complete. Strong work.':`${store.profile.weeklyGoal-store.workoutsThisWeek.length} sessions left to hit your weekly goal.` }}</p></div><RouterLink to="/settings" class="avatar mobile-avatar">{{ store.profile.name[0] }}</RouterLink></header><section class="hero-card"><div class="hero-copy"><span class="hero-kicker"><Flame :size="16"/> {{ store.activeWorkout?'WORKOUT IN PROGRESS':'READY TO TRAIN' }}</span><h2>{{ store.activeWorkout?.title||recommended?.name||'Quick Workout' }}</h2><p v-if="store.activeWorkout">{{ store.completedSets }} of {{ store.totalSets }} sets complete</p><p v-else-if="recommended">{{ routineSubtitle(recommended) }} - {{ recommended.description }}</p><div class="hero-meta"><span><Clock3 :size="16"/> {{ store.activeWorkout?'Timer running':'About 55 min' }}</span><span>{{ store.activeWorkout?.exercises.length||recommended?.exercises.length||0 }} exercises</span></div></div><button class="start-button" @click="start"><span><Play :size="19" fill="currentColor"/> {{ store.activeWorkout?'Resume workout':'Start workout' }}</span><ArrowRight :size="20"/></button></section><div class="section-title"><div><span class="eyebrow">THIS WEEK</span><h2>Your momentum</h2></div><RouterLink to="/progress">View progress <ChevronRight :size="16"/></RouterLink></div><section class="stat-grid"><article class="stat-card"><span class="stat-icon coral"><CalendarDays :size="19"/></span><div><strong>{{ store.workoutsThisWeek.length }}</strong><span>Workouts</span></div><small>Goal {{ store.profile.weeklyGoal }}</small></article><article class="stat-card"><span class="stat-icon lime"><TrendingUp :size="19"/></span><div><strong>{{ Math.round(store.weeklyVolume/1000*10)/10 }}k</strong><span>Volume - {{ store.profile.units }}</span></div><small>Completed work</small></article><article class="stat-card"><span class="stat-icon purple"><Clock3 :size="19"/></span><div><strong>{{ Math.floor(weeklyMinutes/60) }}h {{ weeklyMinutes%60 }}m</strong><span>Training time</span></div><small>{{ store.workoutsThisWeek.length }} sessions</small></article></section><section class="dashboard-grid"><div class="panel recent-panel"><div class="panel-head"><div><span class="eyebrow">RECENT ACTIVITY</span><h2>Last workouts</h2></div><RouterLink to="/history">All history</RouterLink></div><RouterLink v-for="workout in store.history.slice(0,3)" :key="workout.id" :to="`/history/${workout.id}`" class="activity-row"><span class="date-tile"><strong>{{ new Date(workout.startedAt).getDate() }}</strong><small>{{ new Date(workout.startedAt).toLocaleString('en',{month:'short'}) }}</small></span><span><strong>{{ workout.title }}</strong><small>{{ workoutDuration(workout) }} min - {{ Math.round(workoutVolume(workout)).toLocaleString() }} {{ store.profile.units }}</small></span><ChevronRight :size="18"/></RouterLink></div><div class="panel pr-panel"><div class="panel-head"><div><span class="eyebrow">TOP LIFT</span><h2>{{ latestPr.name }}</h2></div><span class="stat-icon amber"><Award :size="19"/></span></div><div class="pr-value"><strong>{{ latestPr.weight||'--' }}</strong><span>{{ store.profile.units }}</span></div><p>{{ latestPr.reps }} reps</p><div class="mini-chart"><svg viewBox="0 0 320 90"><path d="M0 75 C40 70 55 63 82 65 S126 55 150 57 S192 48 214 40 S260 35 320 10" fill="none" stroke="currentColor" stroke-width="3"/></svg></div></div></section><div class="quick-actions"><RouterLink to="/routines/new"><Plus :size="17"/> New routine</RouterLink><button @click="empty"><Plus :size="17"/> Empty workout</button><RouterLink to="/progress"><Plus :size="17"/> Log measurement</RouterLink></div></div></template>
